def subtract(a, b):
    # Flatten and merge overlapping intervals in a
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [i for i in intervals if i[0] < i[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # No overlap
                merged.append([start, end])

        return merged

    merged_a = merge_intervals(a)
    merged_b = merge_intervals(b)

    if not merged_a:
        return []

    if not merged_b:
        return merged_a

    result = []

    for a_start, a_end in merged_a:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_ranges = []

            for c_start, c_end in current_ranges:
                # No overlap between [c_start, c_end) and [b_start, b_end)
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])

            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result.sort()
    merged_result = [result[0]]

    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

